CREATE TABLE tasks (id TEXT PRIMARY KEY, title TEXT NOT NULL, repo TEXT NOT NULL, status TEXT NOT NULL, model TEXT NOT NULL, provider TEXT NOT NULL, session_id TEXT NOT NULL UNIQUE, budget_usd REAL, plan TEXT NOT NULL DEFAULT '[]', checkpoint TEXT, worktree TEXT, cost_usd REAL NOT NULL DEFAULT 0, created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE TABLE task_events (id TEXT PRIMARY KEY, task_id TEXT NOT NULL REFERENCES tasks(id) ON DELETE CASCADE, kind TEXT NOT NULL, message TEXT NOT NULL, output TEXT, duration_ms INTEGER, input_tokens INTEGER NOT NULL DEFAULT 0, output_tokens INTEGER NOT NULL DEFAULT 0, cache_read_tokens INTEGER NOT NULL DEFAULT 0, cache_write_tokens INTEGER NOT NULL DEFAULT 0, cost_usd REAL NOT NULL DEFAULT 0, created_at TEXT NOT NULL);
CREATE INDEX task_events_task_id_created_at ON task_events(task_id, created_at);
